function initialize() {
	debug = "true".equalsIgnoreCase(connector.getParam("detailedLog"))
	syslog = "true".equalsIgnoreCase(connector.getParam("useSyslog"))

	connector.logmsg(RESOLVER.getString("VERSION.INFO", [vrs, LEEFVersion, syslog]));

	if (syslog) {
		syslog_initialize()
	}	

	leef_initialize()
}	

function terminate() {
	if (syslog) {
		syslog_terminate()
	}	

	leef_terminate()
}

function querySchema() {
	var schema = config.getSchema(false);

	if (syslog) {
		syslog_querySchema(schema)
	} 

	leef_querySchema(schema)

	result.setStatus(0)
}

function putEntry() {
	if (syslog) {
		syslog_putEntry(entry)
	} else {
		leef_putEntry(entry)
	}
}

